class PlateProduct(ConfiguredBaseModel):
    """
    Abstract base for plate measurement data products.
    Common summary slots shared across AMP2 and Ecoplate products.

    v1 origin: plate-general.yaml PlateProduct
    v2 change: follows existing satellite-table pattern (id: range: processedData)
               instead of v1's is_a: dataProduct.
    """
    linkml_meta: ClassVar[LinkMLMeta] = LinkMLMeta({'abstract': True,
         'from_schema': 'https://w3id.org/MONet/analysis-api-schema/media-strain-culture-plate',
         'todos': ['add plate_range (12 well, 96 well, etc.)?']})

    wavelength_nm: int = Field(default=..., description="""Measurement wavelength in nanometres (e.g. 590 Ecoplate, 610 AMP2 OD)""", json_schema_extra = { "linkml_meta": {'domain_of': ['AMP2DataGenerationActivity',
                       'EcoplateDataGenerationActivity',
                       'PlateProduct']} })
    timepoint_label: str = Field(default=..., description="""Human-readable timepoint label for repeated-measurement series.
Examples: \"t=0\", \"t=24h\", \"t=48h\".
Lives on concrete analysis/product subclasses, NOT on base DataGenerationActivity""", json_schema_extra = { "linkml_meta": {'domain_of': ['PlateDataGenerationActivity', 'PlateProduct']} })
    plate_average: Optional[float] = Field(default=None, description="""Mean measurement across all sample wells (excludes blanks)""", json_schema_extra = { "linkml_meta": {'domain_of': ['PlateProduct'], 'todos': ['units']} })
    blank_mean: Optional[float] = Field(default=None, description="""Mean measurement of uninoculated control wells""", json_schema_extra = { "linkml_meta": {'domain_of': ['PlateProduct'], 'todos': ['units']} })
    cv_percent: Optional[float] = Field(default=None, description="""Coefficient of variation across technical replicates""", json_schema_extra = { "linkml_meta": {'domain_of': ['PlateProduct']} })
    well_readings: Optional[list[WellReading]] = Field(default=None, description="""Structured per-well measurement data array.
Lightweight summary for SQL queries without full file download.
Raw data still accessible via processedData.s3_key in MinIO.
typed via LinkML inlined class.""", json_schema_extra = { "linkml_meta": {'domain_of': ['PlateProduct'],
         'todos': ['decide how to represent in backend (normalized child table with FK '
                   'to PlateSetupActivity, array column, or other)']} })


