class MediaPreparation(SampleProcessing):
    """
    Activity that prepares a batch of growth media.
    Replaces the former labPreparationActivity + MediaCreation pattern.

    Media details (recipe, formulation, sterilisation, etc.) are carried as
    slots on this activity.  The physical media batch is represented as a
    processedSample(type='prepared_media') linked via processingSampleLink
    (role: output_sample).  Downstream CultureGrowth and AMP2PlateSetupActivity
    activities reference that processedSample via the media_ref FK slot.

    Lifecycle:
      MediaPreparation activity
        -> processingSampleLink(role=output_sample)
        -> processedSample(type='prepared_media'); media_ref points here
        -> CultureGrowth / AMP2PlateSetupActivity.media_ref
    """
    linkml_meta: ClassVar[LinkMLMeta] = LinkMLMeta({'from_schema': 'https://w3id.org/MONet/analysis-api-schema/media-strain-culture-plate',
         'todos': ['storage_condt as enum?', 'media range?']})

    media_type: Optional[MediaTypeEnum] = Field(default=None, description="""Purpose/context of the media preparation.
Examples: strain_purity, stock_culture, pre_culture, rich_media.""", json_schema_extra = { "linkml_meta": {'domain_of': ['MediaPreparation']} })
    volume_ml: Optional[float] = Field(default=None, description="""Volume of the entity in milliliters""", json_schema_extra = { "linkml_meta": {'domain_of': ['MediaPreparation']} })
    media_recipe: Optional[str] = Field(default=None, description="""Reference or description of recipe used to prepare media.
Examples: \"M9 media with 1% Glucose\", \"rich media with 10% LB and 90% glycerol\"""", json_schema_extra = { "linkml_meta": {'domain_of': ['MediaPreparation']} })
    media_formulation: Optional[FormulationEnum] = Field(default=None, description="""Formulation method of the media (manual mix, commercial, etc.)""", json_schema_extra = { "linkml_meta": {'domain_of': ['MediaPreparation']} })
    commercial_media_catalog: Optional[str] = Field(default=None, description="""Reference to commercial media catalog entry if applicable.
Required if media_formulation is 'commercial', otherwise null.""", json_schema_extra = { "linkml_meta": {'domain_of': ['MediaPreparation']} })
    sterilization_method: Optional[SterilizationMethodEnum] = Field(default=None, description="""Method used to sterilize the entity (autoclave, filter, UV, etc.)""", json_schema_extra = { "linkml_meta": {'domain_of': ['MediaPreparation']} })
    ph_adjustment: Optional[bool] = Field(default=None, description="""Whether the entity was pH-adjusted""", json_schema_extra = { "linkml_meta": {'domain_of': ['MediaPreparation']} })
    ph_target: Optional[float] = Field(default=None, description="""Target pH value (required if ph_adjustment is true)""", json_schema_extra = { "linkml_meta": {'domain_of': ['MediaPreparation']} })
    exposure_sensitivity: Optional[list[str]] = Field(default=None, description="""Sensitivity the entity has if exposed (e.g. light-sensitive, oxygen-sensitive)""", json_schema_extra = { "linkml_meta": {'domain_of': ['MediaPreparation']} })
    media_additions: Optional[list[str]] = Field(default=None, description="""Additional components added to the media (antibiotics, inducers, etc.).
Examples: \"100 ug/mL ampicillin\", \"1 mM IPTG\"""", json_schema_extra = { "linkml_meta": {'domain_of': ['MediaPreparation']} })
    storage_temperature: Optional[str] = Field(default=None, description="""Storage temperature for the sample (e.g., \"-80 C\", \"4 C\").""", json_schema_extra = { "linkml_meta": {'domain_of': ['MediaPreparation', 'AMP2UserSample', 'EngineeredStrainSample']} })
